    </marker>
  </defs>
  <rect class="backdrop" x="0" y="0" width="{width}" height="{height}"></rect>
{elements}</svg>
"""

def parse():
    lines = sys.stdin.read().rstrip('\n').split('\n')
    if not lines or (len(lines) == 1 and lines[0] == ""):
        lines = []

    if not lines:
        width, height = 0, 0
    else:
        max_len = max(len(l) for l in lines)
        width = max_len * 8 + 8
        height = len(lines) * 16 + 16

    elements = []

    # Pad lines to max_len
    grid = [list(l.ljust(max_len)) for l in lines]
    used = [[False] * max_len for _ in lines]

    # Very basic text extraction
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if not used[r][c] and ch.isalnum():
                # Extract word
                word = ""
                cc = c
                while cc < max_len and (grid[r][cc].isalnum() or grid[r][cc] in ' .,!?'):
                    word += grid[r][cc]
                    used[r][cc] = True
                    cc += 1
                elements.append(f'  <text x="{c * 8 + 2}" y="{r * 16 + 12}" >{word.rstrip()}</text>\n')

    # Basic horizontal lines
    for r, row in enumerate(grid):
        c = 0
        while c < max_len:
            if grid[r][c] == '-' and not used[r][c]:
                start_c = c
                while c < max_len and grid[r][c] == '-':
                    used[r][c] = True
                    c += 1
                x1 = start_c * 8
                x2 = c * 8
                elements.append(f'  <line x1="{x1}" y1="{r * 16 + 8}" x2="{x2}" y2="{r * 16 + 8}" class="solid"></line>\n')
            else:
                c += 1

    # Vertical lines
    for c in range(max_len):
        r = 0
        while r < len(grid):
            if grid[r][c] == '|' and not used[r][c]:
                start_r = r
                while r < len(grid) and grid[r][c] == '|':
                    used[r][c] = True
                    r += 1
                y1 = start_r * 16
                y2 = r * 16
                elements.append(f'  <line x1="{c * 8 + 4}" y1="{y1}" x2="{c * 8 + 4}" y2="{y2}" class="solid"></line>\n')
            else:
                r += 1

    print(SVG_TEMPLATE.format(width=width, height=height, elements="".join(elements)), end="")

if __name__ == '__main__':
    parse()
