        return

    grid = [list(l.ljust(max_len)) for l in lines]
    used = [[False] * max_len for _ in lines]

    # Pass 1: find text
    for r, row in enumerate(grid):
        c = 0
        while c < max_len:
            ch = row[c]
            if ch.isalnum() and ch not in 'vV^':
                start = c
                word = ""
                while c < max_len and (grid[r][c].isalnum() or grid[r][c] in ' .,!?'):
                    word += grid[r][c]
                    used[r][c] = True
                    c += 1
                elements.append(f'  <text x="{start * 8 + 2}" y="{r * 16 + 12}" >{word.rstrip()}</text>\n')
            else:
                c += 1

    # Pass 2: find rectangles
    for r in range(len(grid)):
        for c in range(max_len):
            if grid[r][c] == '+' and not used[r][c]:
                # find right +
                c2 = c + 1
                while c2 < max_len and grid[r][c2] == '-':
                    c2 += 1
                if c2 < max_len and grid[r][c2] == '+':
                    # find bottom +
                    r2 = r + 1
                    while r2 < len(grid) and grid[r2][c] == '|':
                        r2 += 1
                    if r2 < len(grid) and grid[r2][c] == '+':
                        # check full rect
                        if grid[r2][c2] == '+':
                            # valid rect
                            x = c * 8 + 4
                            y = r * 16 + 8
                            w = (c2 - c) * 8
                            h = (r2 - r) * 16
                            elements.append(f'  <rect x="{x}" y="{y}" width="{w}" height="{h}" class="solid nofill" rx="0"></rect>\n')
                            for r_ in range(r, r2+1):
                                used[r_][c] = True
                                used[r_][c2] = True
                            for c_ in range(c, c2+1):
                                used[r][c_] = True
                                used[r2][c_] = True

    # Pass 3: find arrows
    for r in range(len(grid)):
        for c in range(max_len - 2):
            if grid[r][c:c+3] == ['-', '-', '>'] and not any(used[r][c:c+3]):
                elements.append(f'  <line x1="{c * 8}" y1="{r * 16 + 8}" x2="{(c+1) * 8}" y2="{r * 16 + 8}" class="solid"></line>\n')
                elements.append(f'  <polygon points="{(c+2)*8},{(r)*16+4} {(c+3)*8},{(r)*16+8} {(c+2)*8},{(r)*16+12}" class="filled"></polygon>\n')
                used[r][c] = used[r][c+1] = used[r][c+2] = True
            elif grid[r][c:c+3] == ['<', '-', '-'] and not any(used[r][c:c+3]):
                elements.append(f'  <polygon points="{(c+1)*8},{(r)*16+4} {(c)*8},{(r)*16+8} {(c+1)*8},{(r)*16+12}" class="filled"></polygon>\n')
                elements.append(f'  <line x1="{(c+1) * 8}" y1="{r * 16 + 8}" x2="{(c+3) * 8}" y2="{r * 16 + 8}" class="solid"></line>\n')
                used[r][c] = used[r][c+1] = used[r][c+2] = True

    # Pass 4: Remaining lines
    for r in range(len(grid)):
